import math

def check_solution(a, b):
    return a**2 + 2 * (3**b) == a * (2**(b+1) - 1)

def solve_discriminant(b):
    # D = (2^(b+1) - 1)^2 - 8 * 3^b
    discriminant = (2**(b+1) - 1)**2 - 8 * (3**b)
    if discriminant < 0:
        return None

    K = int(math.sqrt(discriminant))
    if K * K != discriminant:
        return None

    # a = ((2^(b+1) - 1) +/- K) / 2

    numerator1 = (2**(b+1) - 1) + K
    numerator2 = (2**(b+1) - 1) - K

    solutions = []
    if numerator1 % 2 == 0:
        a1 = numerator1 // 2
        if a1 > 0 and check_solution(a1, b):
            solutions.append((a1, b))

    if numerator2 % 2 == 0:
        a2 = numerator2 // 2
        if a2 > 0 and check_solution(a2, b):
            solutions.append((a2, b))

    return solutions

solutions_list = []
for b in range(1, 10): # Checking up to b=9
    solutions = solve_discriminant(b)
    if solutions:
        solutions_list.extend(solutions)

print(solutions_list)

